<script setup>
defineProps({ report: Object });
const stages = { original: '原文件标准', parsed: '解析', chunks: '分块', retrieval: '检索证据', model_input: '实际生成输入', draft: '初次生成', final: '最终回答' };
const labels = { confirmed: '已人工核对', unassessed: '未独立核对', found: '原句已找到', not_found: '原句未找到', unrecorded: '未记录', covered: '语义覆盖', missing: '语义遗漏', incorrect: '语义错误', pending_review: '语义待复核' };
</script>
<template><section class="panel lineage-panel"><h3>内容在哪一步丢失</h3><p v-if="!report">本次运行未记录逐阶段输入，请新建验收运行。历史数据不会推测补齐。</p><template v-else><p>{{ report.note }}</p><div class="lineage-scroll"><table><thead><tr><th>要点</th><th v-for="label in stages" :key="label">{{ label }}</th><th>优先排查</th></tr></thead><tbody><tr v-for="row in report.rows" :key="row.point_id"><td>{{ row.text }}</td><td v-for="(_, stage) in stages" :key="stage"><span>{{ labels[row.stages[stage].status] }}</span><p v-if="stage === 'final'">{{ labels[row.stages.final.semantic_status] }}</p><small v-if="row.stages[stage].mode === 'source_list_composition'">原文清单直接整理，无生成模型调用</small><details v-if="row.stages[stage].matches?.length"><summary>依据</summary><div v-for="(match, i) in row.stages[stage].matches" :key="i"><p>{{ match.source_quote }}</p><small>{{ match.found ? '找到原句' : '未找到原句' }} {{ JSON.stringify(match.locations) }}</small></div></details></td><td>{{ row.first_gap ? stages[row.first_gap] : '未发现原句丢失，仍需语义复核' }}</td></tr></tbody></table></div></template></section></template>
